public class SelectionSorterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("sortedCopy({3,1,2})", "[1, 2, 3]",
                    java.util.Arrays.toString(SelectionSorter.sortedCopy(new int[]{3, 1, 2})));
            check("sortedCopy({9,-3,0,9,2}) duplicates and negatives", "[-3, 0, 2, 9, 9]",
                    java.util.Arrays.toString(SelectionSorter.sortedCopy(new int[]{9, -3, 0, 9, 2})));
            check("sortedCopy({5,4,3,2,1}) reverse", "[1, 2, 3, 4, 5]",
                    java.util.Arrays.toString(SelectionSorter.sortedCopy(new int[]{5, 4, 3, 2, 1})));
            check("sortedCopy({}) empty", "[]",
                    java.util.Arrays.toString(SelectionSorter.sortedCopy(new int[]{})));
            check("sortedCopy({8}) single", "[8]",
                    java.util.Arrays.toString(SelectionSorter.sortedCopy(new int[]{8})));
            int[] original = {4, 1, 3};
            int[] copy = SelectionSorter.sortedCopy(original);
            check("original array unchanged", "[4, 1, 3]",
                    java.util.Arrays.toString(original));
            check("result is a different array object", false, copy == original);
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

